  `created_at` VARCHAR(19) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_ai_calls_created` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `ai_extractions`;
CREATE TABLE `ai_extractions` (
