  `record_id` INT,
  `status` VARCHAR(24) NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'running', 'done', 'failed', 'skipped')),
  `engine` VARCHAR(255),
  `result` TEXT,
  `attempts` INT NOT NULL DEFAULT 0,
  `claimed_at` VARCHAR(19),
  `created_at` VARCHAR(19) NOT NULL,
  `updated_at` VARCHAR(19) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_ai_extractions_status` (`status`),
  UNIQUE KEY `uq_ai_extractions_kind_source_id` (`kind`, `source_id`),
  CONSTRAINT `fk_ai_extractions_0` FOREIGN KEY (`record_id`) REFERENCES `health_records` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `app_secrets`;
CREATE TABLE `app_secrets` (
