  `distance_km` DOUBLE NOT NULL,
  `status` VARCHAR(24) NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'quoted', 'declined', 'closed')),
  `created_at` VARCHAR(19) NOT NULL,
  `updated_at` VARCHAR(19) NOT NULL,
  `outcome` VARCHAR(20),
  PRIMARY KEY (`id`),
  KEY `idx_lab_requests_lab` (`lab_id`, `status`),
  UNIQUE KEY `uq_lab_requests_prescription_id_lab_id` (`prescription_id`, `lab_id`),
  CONSTRAINT `fk_lab_requests_0` FOREIGN KEY (`lab_id`) REFERENCES `labs` (`user_id`),
  CONSTRAINT `fk_lab_requests_1` FOREIGN KEY (`prescription_id`) REFERENCES `prescriptions` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `lab_tests`;
CREATE TABLE `lab_tests` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `name` VARCHAR(255) NOT NULL,
  `code` VARCHAR(20),
  `category` VARCHAR(40) NOT NULL DEFAULT 'Blood',
  `sample_type` VARCHAR(255),
  `fasting` TINYINT(1) NOT NULL DEFAULT 0,
  `mrp_paise` BIGINT,
  `unit` VARCHAR(20),
  `ref_low` DOUBLE,
  `ref_high` DOUBLE,
  `created_by` INT,
  `created_at` VARCHAR(19) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_lab_tests_name` (`name`),
  CONSTRAINT `fk_lab_tests_0` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `labs`;
CREATE TABLE `labs` (
  `user_id` INT NOT NULL,
  `slug` VARCHAR(120) NOT NULL UNIQUE,
  `lab_name` VARCHAR(255) NOT NULL,
  `registration_no` VARCHAR(255) NOT NULL,
  `nabl_no` VARCHAR(255),
  `pathologist_name` VARCHAR(255) NOT NULL,
  `pathologist_reg_no` VARCHAR(255) NOT NULL,
  `gstin` VARCHAR(255),
  `address` TEXT NOT NULL,
  `city` VARCHAR(60) NOT NULL,
  `state` VARCHAR(60),
  `pincode` VARCHAR(6),
  `lat` DOUBLE NOT NULL,
  `lng` DOUBLE NOT NULL,
  `opening_hours` VARCHAR(255),
  `home_collection` TINYINT(1) NOT NULL DEFAULT 0,
  `collection_fee_paise` BIGINT NOT NULL DEFAULT 0,
  `collection_radius_km` DOUBLE NOT NULL DEFAULT 3,
  `flat_discount_percent` DOUBLE,
  `report_hours` INT NOT NULL DEFAULT 24,
  `status` VARCHAR(24) NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'approved', 'rejected', 'suspended')),
  `status_reason` TEXT,
  `created_at` VARCHAR(19) NOT NULL,
  `approved_at` VARCHAR(19),
  `updated_at` VARCHAR(19),
  PRIMARY KEY (`user_id`),
  KEY `idx_labs_geo` (`status`, `lat`, `lng`),
  CONSTRAINT `fk_labs_0` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `login_failures`;
CREATE TABLE `login_failures` (
  `email` VARCHAR(254) NOT NULL,
  `failed_at` VARCHAR(19) NOT NULL,
  KEY `idx_login_failures` (`email`, `failed_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `medicine_orders`;
CREATE TABLE `medicine_orders` (
  `id` VARCHAR(36) NOT NULL,
  `reference` VARCHAR(20) NOT NULL UNIQUE,
  `prescription_id` VARCHAR(36) NOT NULL,
  `pharmacy_id` INT NOT NULL,
  `patient_id` INT NOT NULL,
  `quote_id` INT,
  `source` VARCHAR(20) NOT NULL CHECK (source IN ('quote', 'price_list')),
  `subtotal_paise` BIGINT NOT NULL,
  `delivery_fee_paise` BIGINT NOT NULL DEFAULT 0,
  `total_paise` BIGINT NOT NULL,
  `fulfilment` VARCHAR(10) NOT NULL CHECK (fulfilment IN ('pickup', 'delivery')),
  `delivery_address` TEXT,
  `distance_km` DOUBLE,
  `payment_method` VARCHAR(10) NOT NULL CHECK (payment_method IN ('pharmacy', 'online')),
  `payment_status` VARCHAR(20) NOT NULL CHECK (payment_status IN ('unpaid', 'pending', 'paid', 'refunded', 'refund_failed')),
  `razorpay_order_id` VARCHAR(255),
  `razorpay_payment_id` VARCHAR(255),
  `refund_id` VARCHAR(255),
  `status` VARCHAR(24) NOT NULL CHECK (status IN ('pending_payment', 'placed', 'accepted', 'ready', 'out_for_delivery', 'completed', 'rejected', 'cancelled', 'expired')),
  `status_reason` TEXT,
  `created_at` VARCHAR(19) NOT NULL,
  `updated_at` VARCHAR(19) NOT NULL,
  `delivery_otp` VARCHAR(255),
  `reminded_at` VARCHAR(19),
  PRIMARY KEY (`id`),
  KEY `idx_orders_pharmacy` (`pharmacy_id`, `status`),
  KEY `idx_orders_patient` (`patient_id`),
  KEY `idx_orders_rzp` (`razorpay_order_id`),
  CONSTRAINT `fk_medicine_orders_0` FOREIGN KEY (`quote_id`) REFERENCES `quotes` (`id`),
  CONSTRAINT `fk_medicine_orders_1` FOREIGN KEY (`patient_id`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_medicine_orders_2` FOREIGN KEY (`pharmacy_id`) REFERENCES `pharmacies` (`user_id`),
  CONSTRAINT `fk_medicine_orders_3` FOREIGN KEY (`prescription_id`) REFERENCES `prescriptions` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `medicines`;
CREATE TABLE `medicines` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `name` VARCHAR(255) NOT NULL,
  `generic_name` VARCHAR(255),
  `strength` VARCHAR(40),
  `form` VARCHAR(20),
  `pack_size` INT NOT NULL DEFAULT 1,
  `rx_required` TINYINT(1) NOT NULL DEFAULT 1,
  `created_by` INT,
  `created_at` VARCHAR(19) NOT NULL,
  `mrp_paise` BIGINT,
  `care_area` VARCHAR(40),
  `manufacturer` VARCHAR(255),
  `company_id` INT,
  `salt_key` VARCHAR(255),
  `strength_key` VARCHAR(255),
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_medicines_unique` (`name`, `strength`, `form`),
  KEY `idx_medicines_generic` (`generic_name`, `strength`, `form`),
  KEY `idx_medicines_salt` (`salt_key`, `strength_key`),
  CONSTRAINT `fk_medicines_0` FOREIGN KEY (`company_id`) REFERENCES `companies` (`id`),
  CONSTRAINT `fk_medicines_1` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `messages`;
CREATE TABLE `messages` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `appointment_id` VARCHAR(36) NOT NULL,
  `author_id` INT NOT NULL,
  `author_role` VARCHAR(20) NOT NULL,
  `body` TEXT NOT NULL,
  `created_at` VARCHAR(19) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_messages_appt` (`appointment_id`),
  CONSTRAINT `fk_messages_0` FOREIGN KEY (`author_id`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_messages_1` FOREIGN KEY (`appointment_id`) REFERENCES `appointments` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `mr_requests`;
CREATE TABLE `mr_requests` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `mr_id` INT NOT NULL,
  `doctor_id` INT NOT NULL,
  `company_id` INT NOT NULL,
  `division_id` INT,
  `purpose` TEXT NOT NULL,
  `products` TEXT,
  `preferred_date` VARCHAR(10),
  `preferred_time` VARCHAR(5),
  `status` VARCHAR(24) NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'accepted', 'declined', 'completed', 'cancelled')),
  `doctor_note` TEXT,
  `scheduled_for` VARCHAR(19),
  `created_at` VARCHAR(19) NOT NULL,
  `updated_at` VARCHAR(19) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_mr_requests_doctor` (`doctor_id`, `status`),
  KEY `idx_mr_requests_mr` (`mr_id`),
  CONSTRAINT `fk_mr_requests_0` FOREIGN KEY (`division_id`) REFERENCES `divisions` (`id`),
  CONSTRAINT `fk_mr_requests_1` FOREIGN KEY (`company_id`) REFERENCES `companies` (`id`),
  CONSTRAINT `fk_mr_requests_2` FOREIGN KEY (`doctor_id`) REFERENCES `doctors` (`user_id`),
  CONSTRAINT `fk_mr_requests_3` FOREIGN KEY (`mr_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `mrs`;
CREATE TABLE `mrs` (
  `user_id` INT NOT NULL,
  `company_id` INT NOT NULL,
  `division_id` INT,
  `employee_code` VARCHAR(255),
  `territory_city` VARCHAR(255),
  `territory_state` VARCHAR(255),
  `created_at` VARCHAR(19) NOT NULL,
  PRIMARY KEY (`user_id`),
  KEY `idx_mrs_company` (`company_id`),
  CONSTRAINT `fk_mrs_0` FOREIGN KEY (`division_id`) REFERENCES `divisions` (`id`),
  CONSTRAINT `fk_mrs_1` FOREIGN KEY (`company_id`) REFERENCES `companies` (`id`),
  CONSTRAINT `fk_mrs_2` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `notifications`;
CREATE TABLE `notifications` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `user_id` INT NOT NULL,
  `kind` VARCHAR(24) NOT NULL DEFAULT 'update',
  `title` VARCHAR(255) NOT NULL,
  `body` TEXT,
  `link` VARCHAR(255),
  `created_at` VARCHAR(19) NOT NULL,
  `read_at` VARCHAR(19),
  PRIMARY KEY (`id`),
  KEY `idx_notifications_user` (`user_id`, `read_at`, `id`),
  CONSTRAINT `fk_notifications_0` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `order_items`;
CREATE TABLE `order_items` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `order_id` VARCHAR(36) NOT NULL,
  `prescription_item_id` INT NOT NULL,
  `medicine_id` INT,
  `name` VARCHAR(255) NOT NULL,
  `quantity` INT NOT NULL,
  `unit_price_paise` BIGINT NOT NULL,
  `line_paise` BIGINT NOT NULL,
  PRIMARY KEY (`id`),
  CONSTRAINT `fk_order_items_0` FOREIGN KEY (`medicine_id`) REFERENCES `medicines` (`id`),
  CONSTRAINT `fk_order_items_1` FOREIGN KEY (`prescription_item_id`) REFERENCES `prescription_items` (`id`),
  CONSTRAINT `fk_order_items_2` FOREIGN KEY (`order_id`) REFERENCES `medicine_orders` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `password_resets`;
CREATE TABLE `password_resets` (
  `token_hash` VARCHAR(64) NOT NULL,
  `user_id` INT NOT NULL,
  `expires_at` VARCHAR(19) NOT NULL,
  `used_at` VARCHAR(19),
  PRIMARY KEY (`token_hash`),
  CONSTRAINT `fk_password_resets_0` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `patient_medicines`;
CREATE TABLE `patient_medicines` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `patient_id` INT NOT NULL,
  `name` VARCHAR(255) NOT NULL,
  `strength` VARCHAR(40),
  `dosage` VARCHAR(255),
  `since` VARCHAR(10),
  `prescribed_by` VARCHAR(255),
  `notes` TEXT,
  `active` TINYINT(1) NOT NULL DEFAULT 1,
  `created_at` VARCHAR(19) NOT NULL,
  `updated_at` VARCHAR(19) NOT NULL,
  `generic_name` VARCHAR(255),
  `medicine_id` INT,
  PRIMARY KEY (`id`),
  KEY `idx_patient_medicines` (`patient_id`),
  CONSTRAINT `fk_patient_medicines_0` FOREIGN KEY (`medicine_id`) REFERENCES `medicines` (`id`),
  CONSTRAINT `fk_patient_medicines_1` FOREIGN KEY (`patient_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `payouts`;
CREATE TABLE `payouts` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `payee_role` VARCHAR(255) NOT NULL CHECK (payee_role IN ('doctor', 'pharmacy')),
  `payee_id` INT NOT NULL,
  `amount_paise` BIGINT NOT NULL,
  `reference` VARCHAR(20),
  `note` TEXT,
  `created_by` INT,
  `created_at` VARCHAR(19) NOT NULL,
  PRIMARY KEY (`id`),
  CONSTRAINT `fk_payouts_0` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_payouts_1` FOREIGN KEY (`payee_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `pharmacies`;
CREATE TABLE `pharmacies` (
  `user_id` INT NOT NULL,
  `slug` VARCHAR(120) NOT NULL UNIQUE,
  `store_name` VARCHAR(255) NOT NULL,
  `drug_licence_no` VARCHAR(255) NOT NULL,
  `pharmacist_name` VARCHAR(255) NOT NULL,
  `pharmacist_reg_no` VARCHAR(255) NOT NULL,
  `gstin` VARCHAR(255),
  `address` TEXT NOT NULL,
  `city` VARCHAR(60) NOT NULL,
  `pincode` VARCHAR(6),
  `lat` DOUBLE NOT NULL,
  `lng` DOUBLE NOT NULL,
  `opening_hours` VARCHAR(255),
  `offers_delivery` TINYINT(1) NOT NULL DEFAULT 0,
  `delivery_radius_km` DOUBLE NOT NULL DEFAULT 3,
  `delivery_fee_paise` BIGINT NOT NULL DEFAULT 0,
  `accepts_online_payment` TINYINT(1) NOT NULL DEFAULT 0,
  `status` VARCHAR(24) NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'approved', 'rejected', 'suspended')),
  `status_reason` TEXT,
  `created_at` VARCHAR(19) NOT NULL,
  `approved_at` VARCHAR(19),
  `updated_at` VARCHAR(19),
  `flat_discount_percent` DOUBLE,
  `pickup_ready_minutes` INT NOT NULL DEFAULT 15,
  `delivery_minutes` INT NOT NULL DEFAULT 60,
  `state` VARCHAR(60),
  PRIMARY KEY (`user_id`),
  KEY `idx_pharmacies_geo` (`status`, `lat`, `lng`),
  CONSTRAINT `fk_pharmacies_0` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `pharmacy_stock`;
CREATE TABLE `pharmacy_stock` (
  `pharmacy_id` INT NOT NULL,
  `medicine_id` INT NOT NULL,
  `mrp_paise` BIGINT NOT NULL,
  `price_paise` BIGINT NOT NULL,
  `in_stock` TINYINT(1) NOT NULL DEFAULT 1,
  `updated_at` VARCHAR(19) NOT NULL,
  `on_hand` INT,
  PRIMARY KEY (`pharmacy_id`, `medicine_id`),
  KEY `idx_stock_medicine` (`medicine_id`),
  CONSTRAINT `fk_pharmacy_stock_0` FOREIGN KEY (`medicine_id`) REFERENCES `medicines` (`id`),
  CONSTRAINT `fk_pharmacy_stock_1` FOREIGN KEY (`pharmacy_id`) REFERENCES `pharmacies` (`user_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `prescription_conditions`;
CREATE TABLE `prescription_conditions` (
  `prescription_id` VARCHAR(36) NOT NULL,
  `condition_id` INT NOT NULL,
  PRIMARY KEY (`prescription_id`, `condition_id`),
  KEY `idx_rx_conditions_condition` (`condition_id`),
  CONSTRAINT `fk_prescription_conditions_0` FOREIGN KEY (`condition_id`) REFERENCES `conditions` (`id`),
  CONSTRAINT `fk_prescription_conditions_1` FOREIGN KEY (`prescription_id`) REFERENCES `prescriptions` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `prescription_items`;
CREATE TABLE `prescription_items` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `prescription_id` VARCHAR(36) NOT NULL,
  `medicine_id` INT,
  `name` VARCHAR(255) NOT NULL,
  `generic_name` VARCHAR(255),
  `strength` VARCHAR(40),
  `form` VARCHAR(20),
  `dosage` VARCHAR(255),
  `duration` VARCHAR(255),
  `quantity` INT NOT NULL,
  `instructions` TEXT,
  `allow_substitute` TINYINT(1) NOT NULL DEFAULT 1,
  `daily_units` DOUBLE,
  `duration_days` INT,
  `is_long_term` TINYINT(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  KEY `idx_rx_items_rx` (`prescription_id`),
  CONSTRAINT `fk_prescription_items_0` FOREIGN KEY (`medicine_id`) REFERENCES `medicines` (`id`),
  CONSTRAINT `fk_prescription_items_1` FOREIGN KEY (`prescription_id`) REFERENCES `prescriptions` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `prescription_tests`;
CREATE TABLE `prescription_tests` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `prescription_id` VARCHAR(36) NOT NULL,
  `test_id` INT,
  `name` VARCHAR(255) NOT NULL,
  `instructions` TEXT,
  PRIMARY KEY (`id`),
  KEY `idx_rx_tests` (`prescription_id`),
  CONSTRAINT `fk_prescription_tests_0` FOREIGN KEY (`test_id`) REFERENCES `lab_tests` (`id`),
  CONSTRAINT `fk_prescription_tests_1` FOREIGN KEY (`prescription_id`) REFERENCES `prescriptions` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `prescriptions`;
CREATE TABLE `prescriptions` (
  `id` VARCHAR(36) NOT NULL,
  `reference` VARCHAR(20) NOT NULL UNIQUE,
  `appointment_id` VARCHAR(36),
  `doctor_id` INT NOT NULL,
  `patient_id` INT NOT NULL,
  `patient_age` INT,
  `patient_sex` VARCHAR(255),
  `diagnosis` TEXT,
  `advice` TEXT,
  `lat` DOUBLE,
  `lng` DOUBLE,
  `location_source` VARCHAR(20),
  `radius_km` DOUBLE NOT NULL,
  `status` VARCHAR(24) NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'cancelled')),
  `created_at` VARCHAR(19) NOT NULL,
  `valid_until` VARCHAR(19) NOT NULL,
  `expiry_reminded_at` VARCHAR(19),
  `parent_id` VARCHAR(36),
  `refill_number` INT NOT NULL DEFAULT 0,
  `refills_allowed` INT NOT NULL DEFAULT 0,
  `refills_used` INT NOT NULL DEFAULT 0,
  `refill_until` VARCHAR(19),
  `refill_reminded_at` VARCHAR(19),
  `family_member_id` INT,
  `follow_up_on` VARCHAR(255),
  `follow_up_reminded_at` VARCHAR(19),
  `pregnancy` VARCHAR(255),
  `safety_alerts` TEXT,
  `safety_ack_at` VARCHAR(19),
  PRIMARY KEY (`id`),
  KEY `idx_rx_patient` (`patient_id`),
  KEY `idx_rx_doctor` (`doctor_id`),
  KEY `idx_rx_created` (`created_at`),
  KEY `idx_rx_parent` (`parent_id`),
  CONSTRAINT `fk_prescriptions_0` FOREIGN KEY (`family_member_id`) REFERENCES `family_members` (`id`),
  CONSTRAINT `fk_prescriptions_1` FOREIGN KEY (`parent_id`) REFERENCES `prescriptions` (`id`),
  CONSTRAINT `fk_prescriptions_2` FOREIGN KEY (`patient_id`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_prescriptions_3` FOREIGN KEY (`doctor_id`) REFERENCES `doctors` (`user_id`),
  CONSTRAINT `fk_prescriptions_4` FOREIGN KEY (`appointment_id`) REFERENCES `appointments` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `quote_items`;
CREATE TABLE `quote_items` (
  `quote_id` INT NOT NULL,
  `prescription_item_id` INT NOT NULL,
  `available` TINYINT(1) NOT NULL,
  `supplied_name` VARCHAR(255),
  `unit_price_paise` BIGINT NOT NULL DEFAULT 0,
  `quantity` INT NOT NULL,
  `line_paise` BIGINT NOT NULL DEFAULT 0,
  `mrp_paise` BIGINT,
  CONSTRAINT `fk_quote_items_0` FOREIGN KEY (`prescription_item_id`) REFERENCES `prescription_items` (`id`),
  CONSTRAINT `fk_quote_items_1` FOREIGN KEY (`quote_id`) REFERENCES `quotes` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `quotes`;
CREATE TABLE `quotes` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `prescription_id` VARCHAR(36) NOT NULL,
  `pharmacy_id` INT NOT NULL,
  `subtotal_paise` BIGINT NOT NULL,
  `delivery_available` TINYINT(1) NOT NULL DEFAULT 0,
  `delivery_fee_paise` BIGINT NOT NULL DEFAULT 0,
  `ready_in_minutes` INT,
  `note` TEXT,
  `status` VARCHAR(24) NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'withdrawn', 'accepted', 'lost')),
  `created_at` VARCHAR(19) NOT NULL,
  `valid_until` VARCHAR(19) NOT NULL,
  `delivery_minutes` INT,
  PRIMARY KEY (`id`),
  KEY `idx_quotes_rx` (`prescription_id`, `status`),
  CONSTRAINT `fk_quotes_0` FOREIGN KEY (`pharmacy_id`) REFERENCES `pharmacies` (`user_id`),
  CONSTRAINT `fk_quotes_1` FOREIGN KEY (`prescription_id`) REFERENCES `prescriptions` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `rate_limits`;
CREATE TABLE `rate_limits` (
  `key` VARCHAR(255) NOT NULL,
  `hit_at` VARCHAR(19) NOT NULL,
  KEY `idx_rate_limits` (`key`, `hit_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `record_values`;
CREATE TABLE `record_values` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `record_id` INT NOT NULL,
  `test_id` INT,
  `name` VARCHAR(255) NOT NULL,
  `value_num` DOUBLE,
  `value_text` TEXT,
  `unit` VARCHAR(20),
  `ref_low` DOUBLE,
  `ref_high` DOUBLE,
  `flag` VARCHAR(10) CHECK (flag IN ('low', 'normal', 'high')),
  PRIMARY KEY (`id`),
  KEY `idx_record_values` (`record_id`),
  CONSTRAINT `fk_record_values_0` FOREIGN KEY (`test_id`) REFERENCES `lab_tests` (`id`),
  CONSTRAINT `fk_record_values_1` FOREIGN KEY (`record_id`) REFERENCES `health_records` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `reviews`;
CREATE TABLE `reviews` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `patient_id` INT NOT NULL,
  `target_role` VARCHAR(20) NOT NULL CHECK (target_role IN ('doctor', 'pharmacy')),
  `target_id` INT NOT NULL,
  `appointment_id` VARCHAR(36) UNIQUE,
  `order_id` VARCHAR(36) UNIQUE,
  `rating` INT NOT NULL CHECK (rating BETWEEN 1 AND 5),
  `comment` VARCHAR(255),
  `created_at` VARCHAR(19) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_reviews_target` (`target_role`, `target_id`),
  CONSTRAINT `fk_reviews_0` FOREIGN KEY (`order_id`) REFERENCES `medicine_orders` (`id`),
  CONSTRAINT `fk_reviews_1` FOREIGN KEY (`appointment_id`) REFERENCES `appointments` (`id`),
  CONSTRAINT `fk_reviews_2` FOREIGN KEY (`target_id`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_reviews_3` FOREIGN KEY (`patient_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `rx_requests`;
CREATE TABLE `rx_requests` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `prescription_id` VARCHAR(36) NOT NULL,
  `pharmacy_id` INT NOT NULL,
  `distance_km` DOUBLE NOT NULL,
  `status` VARCHAR(24) NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'quoted', 'declined', 'closed')),
  `created_at` VARCHAR(19) NOT NULL,
  `updated_at` VARCHAR(19) NOT NULL,
  `outcome` VARCHAR(20),
  PRIMARY KEY (`id`),
  KEY `idx_requests_pharmacy` (`pharmacy_id`, `status`),
  UNIQUE KEY `uq_rx_requests_prescription_id_pharmacy_id` (`prescription_id`, `pharmacy_id`),
  CONSTRAINT `fk_rx_requests_0` FOREIGN KEY (`pharmacy_id`) REFERENCES `pharmacies` (`user_id`),
  CONSTRAINT `fk_rx_requests_1` FOREIGN KEY (`prescription_id`) REFERENCES `prescriptions` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `rx_uploads`;
CREATE TABLE `rx_uploads` (
  `id` VARCHAR(36) NOT NULL,
  `reference` VARCHAR(20) NOT NULL UNIQUE,
  `patient_id` INT NOT NULL,
  `record_id` INT NOT NULL,
  `want_medicines` TINYINT(1) NOT NULL DEFAULT 1,
  `want_tests` TINYINT(1) NOT NULL DEFAULT 0,
  `note` TEXT,
  `lat` DOUBLE NOT NULL,
  `lng` DOUBLE NOT NULL,
  `radius_km` DOUBLE NOT NULL,
  `status` VARCHAR(24) NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'closed', 'cancelled')),
  `created_at` VARCHAR(19) NOT NULL,
  `valid_until` VARCHAR(19) NOT NULL,
  `ai_read_consent` TINYINT(1) NOT NULL DEFAULT 0,
  `typed_lines` TEXT,
  PRIMARY KEY (`id`),
  KEY `idx_rx_uploads_patient` (`patient_id`),
  CONSTRAINT `fk_rx_uploads_0` FOREIGN KEY (`record_id`) REFERENCES `health_records` (`id`),
  CONSTRAINT `fk_rx_uploads_1` FOREIGN KEY (`patient_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `services`;
CREATE TABLE `services` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `doctor_id` INT NOT NULL,
  `name` VARCHAR(255) NOT NULL,
  `duration` INT NOT NULL,
  `fee` INT NOT NULL,
  `active` TINYINT(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  CONSTRAINT `fk_services_0` FOREIGN KEY (`doctor_id`) REFERENCES `doctors` (`user_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `sessions`;
CREATE TABLE `sessions` (
  `token_hash` VARCHAR(64) NOT NULL,
  `user_id` INT NOT NULL,
  `created_at` VARCHAR(19) NOT NULL,
  `expires_at` VARCHAR(19) NOT NULL,
  PRIMARY KEY (`token_hash`),
  CONSTRAINT `fk_sessions_0` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `upload_orders`;
CREATE TABLE `upload_orders` (
  `id` VARCHAR(36) NOT NULL,
  `reference` VARCHAR(20) NOT NULL UNIQUE,
  `upload_id` VARCHAR(36) NOT NULL,
  `quote_id` INT NOT NULL,
  `patient_id` INT NOT NULL,
  `partner_role` VARCHAR(10) NOT NULL CHECK (partner_role IN ('pharmacy', 'lab')),
  `partner_id` INT NOT NULL,
  `fulfilment` VARCHAR(10) NOT NULL CHECK (fulfilment IN ('pickup', 'delivery', 'visit', 'home')),
  `address` TEXT,
  `preferred_date` VARCHAR(10),
  `preferred_time` VARCHAR(5),
  `subtotal_paise` BIGINT NOT NULL,
  `fee_paise` BIGINT NOT NULL DEFAULT 0,
  `total_paise` BIGINT NOT NULL,
  `payment_status` VARCHAR(20) NOT NULL DEFAULT 'unpaid' CHECK (payment_status IN ('unpaid', 'paid')),
  `status` VARCHAR(24) NOT NULL CHECK (status IN ('placed', 'accepted', 'ready', 'sample_collected', 'report_ready', 'completed', 'rejected', 'cancelled')),
  `status_reason` TEXT,
  `handover_code` VARCHAR(255),
  `created_at` VARCHAR(19) NOT NULL,
  `updated_at` VARCHAR(19) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_upload_orders_partner` (`partner_id`, `status`),
  KEY `idx_upload_orders_patient` (`patient_id`),
  CONSTRAINT `fk_upload_orders_0` FOREIGN KEY (`partner_id`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_upload_orders_1` FOREIGN KEY (`patient_id`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_upload_orders_2` FOREIGN KEY (`quote_id`) REFERENCES `upload_quotes` (`id`),
  CONSTRAINT `fk_upload_orders_3` FOREIGN KEY (`upload_id`) REFERENCES `rx_uploads` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `upload_quote_lines`;
CREATE TABLE `upload_quote_lines` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `quote_id` INT NOT NULL,
  `name` VARCHAR(255) NOT NULL,
  `quantity` INT NOT NULL,
  `available` TINYINT(1) NOT NULL DEFAULT 1,
  `unit_price_paise` BIGINT NOT NULL DEFAULT 0,
  `mrp_paise` BIGINT,
  `medicine_id` INT,
  PRIMARY KEY (`id`),
  CONSTRAINT `fk_upload_quote_lines_0` FOREIGN KEY (`medicine_id`) REFERENCES `medicines` (`id`),
  CONSTRAINT `fk_upload_quote_lines_1` FOREIGN KEY (`quote_id`) REFERENCES `upload_quotes` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `upload_quotes`;
CREATE TABLE `upload_quotes` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `upload_id` VARCHAR(36) NOT NULL,
  `partner_role` VARCHAR(10) NOT NULL CHECK (partner_role IN ('pharmacy', 'lab')),
  `partner_id` INT NOT NULL,
  `subtotal_paise` BIGINT NOT NULL,
  `mrp_total_paise` BIGINT NOT NULL,
  `lines_total` INT NOT NULL,
  `lines_available` INT NOT NULL,
  `delivery_available` TINYINT(1) NOT NULL DEFAULT 0,
  `delivery_fee_paise` BIGINT NOT NULL DEFAULT 0,
  `ready_minutes` INT,
  `delivery_minutes` INT,
  `note` TEXT,
  `status` VARCHAR(24) NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'withdrawn', 'accepted', 'lost')),
  `created_at` VARCHAR(19) NOT NULL,
  `valid_until` VARCHAR(19) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_upload_quotes` (`upload_id`, `status`),
  CONSTRAINT `fk_upload_quotes_0` FOREIGN KEY (`partner_id`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_upload_quotes_1` FOREIGN KEY (`upload_id`) REFERENCES `rx_uploads` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `upload_requests`;
CREATE TABLE `upload_requests` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `upload_id` VARCHAR(36) NOT NULL,
  `partner_role` VARCHAR(10) NOT NULL CHECK (partner_role IN ('pharmacy', 'lab')),
  `partner_id` INT NOT NULL,
  `distance_km` DOUBLE NOT NULL,
  `status` VARCHAR(24) NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'quoted', 'declined', 'closed')),
  `created_at` VARCHAR(19) NOT NULL,
  `updated_at` VARCHAR(19) NOT NULL,
  `outcome` VARCHAR(20),
  PRIMARY KEY (`id`),
  KEY `idx_upload_requests_partner` (`partner_id`, `status`),
  UNIQUE KEY `uq_upload_requests_upload_id_partner_id` (`upload_id`, `partner_id`),
  CONSTRAINT `fk_upload_requests_0` FOREIGN KEY (`partner_id`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_upload_requests_1` FOREIGN KEY (`upload_id`) REFERENCES `rx_uploads` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `users`;
CREATE TABLE `users` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `role` VARCHAR(20) NOT NULL CHECK (role IN ('patient', 'doctor', 'admin', 'pharmacy', 'company', 'mr', 'lab')),
  `name` VARCHAR(255) NOT NULL,
  `email` VARCHAR(254) NOT NULL UNIQUE,
  `phone` VARCHAR(20),
  `password_hash` VARCHAR(255) NOT NULL,
  `is_active` TINYINT(1) NOT NULL DEFAULT 1,
  `created_at` VARCHAR(19) NOT NULL,
  `last_login_at` VARCHAR(19),
  `home_address` TEXT,
  `home_lat` DOUBLE,
  `home_lng` DOUBLE,
  `share_consent_at` VARCHAR(19),
  `dob` VARCHAR(10),
  `sex` VARCHAR(10),
  `deleted_at` VARCHAR(19),
  `city` VARCHAR(60),
  `state` VARCHAR(60),
  `blood_group` VARCHAR(255),
  `allergies` VARCHAR(255),
  `chronic_conditions` VARCHAR(255),
  `emergency_name` VARCHAR(255),
  `emergency_phone` VARCHAR(255),
  `remind_times` VARCHAR(255),
  `dose_email_digest` INT NOT NULL DEFAULT 0,
  `dose_digest_on` VARCHAR(255),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

